<?php require_once '../config/auth.php';$page_title='Customer';$base='../';$id=(int)($_GET['id']??0);$r=['name'=>'','email'=>'','phone'=>'','company'=>'','status'=>'active','industry'=>'','address'=>'','notes'=>''];if($id){$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$r=$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){$d=[trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['company']),$_POST['status'],trim($_POST['industry']),trim($_POST['address']),trim($_POST['notes'])];if($id)$pdo->prepare('UPDATE customers SET name=?,email=?,phone=?,company=?,status=?,industry=?,address=?,notes=? WHERE id=?')->execute([...$d,$id]);else$pdo->prepare('INSERT INTO customers(name,email,phone,company,status,industry,address,notes) VALUES(?,?,?,?,?,?,?,?)')->execute($d);header('Location:index.php');exit;}include '../partials/header.php';?><div class="cardx"><h4><?=$id?'Edit':'Add'?> Customer</h4><form method="post"><div class="row g-3 mt-1"><div class="col-md-6"><label>Name</label><input required class="form-control" name="name" value="<?=e($r['name'])?>"></div><div class="col-md-6"><label>Email</label><input class="form-control" type="email" name="email" value="<?=e($r['email'])?>"></div><div class="col-md-4"><label>Phone</label><input class="form-control" name="phone" value="<?=e($r['phone'])?>"></div><div class="col-md-4"><label>Company</label><input class="form-control" name="company" value="<?=e($r['company'])?>"></div><div class="col-md-4"><label>Industry</label><input class="form-control" name="industry" value="<?=e($r['industry'])?>"></div><div class="col-md-4"><label>Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','vip'] as $x):?><option <?=$r['status']==$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-8"><label>Address</label><input class="form-control" name="address" value="<?=e($r['address'])?>"></div><div class="col-12"><label>Notes</label><textarea class="form-control" name="notes" rows="4"><?=e($r['notes'])?></textarea></div></div><button class="btn btn-primary mt-4">Save customer</button></form></div><?php include '../partials/footer.php';?>